def actor(conn, email):
    row = conn.execute("""SELECT a.email, a.tenant_id, t.timezone, t.name AS tenant
        FROM admins a JOIN tenants t ON t.id = a.tenant_id WHERE a.email = ?""", (email,)).fetchone()
